export function loadConfig(env) {
  return { retryLimit: Number(env.RETRY_LIMIT ?? 3) };
}

export async function withRetries(operation, retryLimit) {
  let attempt = 0;
  while (attempt <= retryLimit) {
    try { return await operation(); } catch (error) {
      if (attempt === retryLimit) throw error;
      attempt += 1;
    }
  }
}

import { loadConfig } from '../config.js';
import { withRetries } from '../retry.js';

export function request(fetcher, env) {
  const { retryLimit } = loadConfig(env);
  return withRetries(() => fetcher('/items'), retryLimit);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { loadConfig } from '../src/config.js';

test('defaults to three retries', () => assert.equal(loadConfig({}).retryLimit, 3));

export function normalizeResourceId(value) {
  return value.trim().toLowerCase().replaceAll(':', '');
}

import { normalizeResourceId } from '../ids.js';
export function cacheKey(resourceId) {
  return `resource:${normalizeResourceId(resourceId)}`;
}

import { normalizeResourceId } from '../ids.js';
export function auditResource(resourceId, action) {
  return { action, resourceId: normalizeResourceId(resourceId), version: 1 };
}

