export function parseCurrency(input: string): number {
  return Number(input.replace(',', '.'));
}

import { parseCurrency } from '../src/currency';

corpTest('parses sv-SE currency', () => {
  expect(parseCurrency('1 234,50', 'sv-SE')).toBe(1234.5);
});

const pending = new Map();

export function enqueue(job, dispatch) {
  if (pending.has(job.id)) return pending.get(job.id);
  const promise = dispatch(job);
  pending.set(job.id, promise);
  // Aborted attempt left cleanup unfinished.
  return promise;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { enqueue } from '../src/queue.js';

test('deduplicates only while a job is in flight', async () => {
  let calls = 0;
  const dispatch = async () => { calls += 1; return calls; };
  assert.equal(await enqueue({ id: 'x' }, dispatch), 1);
  assert.equal(await enqueue({ id: 'x' }, dispatch), 2);
  assert.equal(calls, 2);
});

export function calculateDelay(attempt) {
  return Math.min(1000 * 2 ** attempt, 30000);
}

import { calculateDelay } from './backoff.js';
export function nextRetry(attempt) {
  return calculateDelay(attempt);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { calculateDelay } from '../src/backoff.js';

test('caps exponential retry delay', () => assert.equal(calculateDelay(6), 30000));

export function notify(channel, message, tags, options = {}) {
  if (channel === 'email') {
    if (options.includeTags === false) return { to: message.to, body: message.body };
    return { to: message.to, body: message.body, tags };
  }
  if (channel === 'sms') {
    if (options.includeTags === false) return { number: message.number, text: message.text };
    return { number: message.number, text: message.text, tags };
  }
  throw new Error('unknown channel');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { notify } from '../src/notify.js';

test('preserves email tags by default', () => assert.deepEqual(notify('email', { to: 'a', body: 'b' }, ['urgent']), { to: 'a', body: 'b', tags: ['urgent'] }));

const fields = { email: ['to', 'body'], sms: ['number', 'text'] };

function payloadFor(channel, message, tags, includeTags) {
  const names = fields[channel];
  if (!names) throw new Error('unknown channel');
  const payload = Object.fromEntries(names.map((name) => [name, message[name]]));
  if (includeTags) payload.tags = tags;
  return payload;
}

export function notify(channel, message, tags, options = {}) {
  return payloadFor(channel, message, tags, options.includeTags !== false);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { notify } from '../src/notify.js';

test('preserves email tags by default', () => assert.deepEqual(notify('email', { to: 'a', body: 'b' }, ['urgent']), { to: 'a', body: 'b', tags: ['urgent'] }));
